contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call run with parameters that perform a transfer from this contract to a recipient
    // after ensuring this contract has enough token balance and that recipient has no special role.
    // The rule asserts that if either sender or recipient is an allowed role, but the transfer amount
    // is strictly less than minTxnAmount, then balances change by exactly the transfer amount and
    // txReward for both parties does not increase.

    function run(address recipient, uint256 transferAmount) public payable {
        require(recipient != address(0));
        // Ensure transferAmount > 0 to avoid zero-transfer path
        require(transferAmount > 0);

        // Observables before
        uint256 minTxn = c.minTxnAmount();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeSenderReward = c.txReward(address(this));
        uint256 beforeRecipientReward = c.txReward(recipient);

        // Precondition: we need this contract to be an "allowed role" so the branch for
        // _tokenBuyTransferReward or _tokenSellTransferReward is exercised. The contract C
        // exposes no setter for allowed roles, but its constructor sets _owner to deployer and
        // onlyOwner functions exist; however allowed roles are private. We cannot set allowed
        // roles directly. Instead, we can still exercise the generic transfer branch by making
        // sure at least one side has allowed role — but since we cannot change roles, we instead
        // assert a rule that holds regardless: if transferAmount < minTxnAmount then even in
        // the specialized reward branches no reward should be given. To drive a transfer that
        // changes state we must ensure this contract has enough tokens and allowance isn't needed
        // because we will call c.transfer(recipient, amount) as msg.sender being this contract

        // We need to possess tokens: on construction of C, msg.sender (deployer) received the mint.
        // In the test environment the deployer of C is external and our contract may not have tokens.
        // But the checker deploys a fresh C and then deploys this test with that C instance; thus
        // address(this) currently has zero tokens. To get tokens, we attempt to transfer from owner
        // to this contract by calling c.transferFrom(owner, address(this), amount). However that needs
        // allowance. Because of these limitations, we'll instead rely on making the transfer from the
        // owner by calling c.transfer(recipient, amount) using msg.sender=this contract is not owner.
        // To avoid needing balances we will only reason about the case where the transfer reverts due to
        // insufficient balance; in that situation balances do not change and txReward does not increase.
        // So we capture whether transfer reverts and assert that if transferAmount < minTxnAmount then
        // no txReward increase happens and if transfer succeeded balances changed by exactly amount.

        bool reverted;
        try c.transfer(recipient, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterSenderReward = c.txReward(address(this));
        uint256 afterRecipientReward = c.txReward(recipient);

        // General rule asserted:
        // If transferAmount < minTxn, then no txReward increases for sender or recipient.
        // Additionally, if the transfer did not revert then balances changed by exactly transferAmount
        // (sender decreased, recipient increased) — otherwise they remain unchanged.
        assert(
            // txReward didn't increase when transfer < minTxn
            (transferAmount < minTxn ? (afterSenderReward == beforeSenderReward && afterRecipientReward == beforeRecipientReward) : true)
            &&
            // If transfer succeeded, balances changed exactly by transferAmount
            (reverted ? (afterSenderBal == beforeSenderBal && afterRecipientBal == beforeRecipientBal)
                      : (beforeSenderBal >= transferAmount && afterSenderBal + transferAmount == beforeSenderBal && afterRecipientBal == beforeRecipientBal + transferAmount))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that performs a transfer from this contract to `recipient` of `transferAmount`.
    // We observe pre/post balances and txReward and whether the call reverted, then assert the general rule.
    function run(address recipient, uint256 transferAmount) public payable {
        require(recipient != address(0));

        // Read observables before the state-changing call
        uint256 minTxn = c.minTxnAmount();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeSenderReward = c.txReward(address(this));
        uint256 beforeRecipientReward = c.txReward(recipient);

        // Perform the transfer and catch revert
        bool reverted;
        try c.transfer(recipient, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterSenderReward = c.txReward(address(this));
        uint256 afterRecipientReward = c.txReward(recipient);

        // Assert the general rule:
        // - If transferAmount < minTxnAmount then neither sender nor recipient receive txReward increase.
        // - If the transfer reverted then balances and txRewards remain unchanged.
        // - If the transfer did not revert then balances change exactly by transferAmount (sender decreases, recipient increases).
        assert(
            // reward condition for amounts below minTxn
            (transferAmount < minTxn ? (afterSenderReward == beforeSenderReward && afterRecipientReward == beforeRecipientReward) : true)
            // if reverted: no changes at all
            && (reverted ? (
                    afterSenderBal == beforeSenderBal
                    && afterRecipientBal == beforeRecipientBal
                    && afterSenderReward == beforeSenderReward
                    && afterRecipientReward == beforeRecipientReward
                ) : (
                    // not reverted: balances updated exactly by transferAmount
                    // avoid underflow by expressing equality as sums
                    (beforeSenderBal == afterSenderBal + transferAmount)
                    && (afterRecipientBal == beforeRecipientBal + transferAmount)
                ))
        );
    }

    receive() external payable {}
}

