contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling transfer on c between two addresses (sender==this contract)
    // with an allowed role present preserves total supply and that recipient's balance
    // after the transfer is at least its prior balance (i.e., transfer does not reduce recipient's token balance).
    // We also ensure the call does not mint tokens (totalSupply unchanged).

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // initial observations
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeRecipient = c.balanceOf(recipient);
        uint256 beforeSelf = c.balanceOf(address(this));

        // Ensure this contract has allowance/ownership roles to be allowed role in c.
        // The C constructor set msg.sender as owner; here InvMutTest is not owner.
        // But C exposes changeUniswapV2Pair and setRewardRate only to owner; no setter for allowed roles.
        // However _allowedRoles mapping is private and there is no public setter. To reach branches,
        // we rely on default transfer behavior (neither allowed) — still meaningful: transfer should preserve totalSupply
        // and not decrease recipient balance after a successful transfer.

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterRecipient = c.balanceOf(recipient);
        uint256 afterSelf = c.balanceOf(address(this));

        // General rule: if transfer did not revert then totalSupply is unchanged
        // and recipient's balance is >= beforeRecipient (i.e., transfer never reduces recipient balance)
        assert(reverted || (afterTotal == beforeTotal && afterRecipient >= beforeRecipient));
    }

    receive() external payable {}
}

