contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: transferring between two allowed-role addresses should move tokens between them
    // without changing totalSupply. We call changeOwner to become owner then set roles via
    // changeOwner is onlyOwner so our contract becomes owner and can call changeOwner.
    // However _allowedRoles is private and there is no public setter; instead the contract
    // constructor of C marks deployer as owner and mints tokens to deployer. The only way
    // to make both sender and recipient be allowed roles is if one of them is the original
    // owner or pair; since _allowedRoles is private and inaccessible, we instead rely on
    // the public transfer function behavior when neither is allowed role: balances move by tAmount.
    // The invariant we assert: for any two addresses a,b and amount, if transfer does not revert,
    // then balanceOf(a) decreases by tAmount (if sufficient) and balanceOf(b) increases by tAmount,
    // and totalSupply unchanged. Because we can't assume preconditions about allowances etc.,
    // we phrase it as: when transfer via c.transferFrom or c.transfer is non-reverting, the
    // difference in sum of balances equals zero except the moved tAmount.

    // To ensure calls originate from this contract, we use transferFrom with prior approve by the
    // token owner (which is address(this) only if minted to it). But constructor of C minted to deployer
    // (the test runner), not to this contract. So we will attempt transfers where this contract is sender
    // by calling transfer on c (msg.sender = this contract) after approving nothing: this may revert.

    // Simpler approach: call c.transfer(recipient, amount) and observe whether it reverted.
    // If it didn't revert, then balances change by exactly amount: before sender balance - after sender balance ==
    // after recipient balance - before recipient balance == amount. Also totalSupply unchanged.

    // All behavior is driven from this single function.
    function run(address senderLike, address recipient, uint256 amount) public payable {
        require(senderLike != address(0) && recipient != address(0));

        // Read observable before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeSender = c.balanceOf(senderLike);
        uint256 beforeRecipient = c.balanceOf(recipient);

        bool reverted = false;
        // We want to perform the transfer as if msg.sender is senderLike, but that's not possible here.
        // Instead, try calling transferFrom where this contract is msg.sender and senderLike is the from.
        // It will succeed only if senderLike previously approved this contract. That's fine: we catch revert.
        try c.transferFrom(senderLike, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterSender = c.balanceOf(senderLike);
        uint256 afterRecipient = c.balanceOf(recipient);

        // If the call reverted then no state change in c is observable for that attempted call.
        // If it did not revert then the amount must have moved from senderLike to recipient
        // (balance decrease and increase by amount) and totalSupply must stay same.
        assert(reverted || (
            // totalSupply unchanged
            afterTotal == beforeTotal
            // balances changed consistently: sender decreased by amount and recipient increased by amount
            && beforeSender >= amount
            && beforeSender - afterSender == amount
            && afterRecipient - beforeRecipient == amount
        ));
    }

    receive() external payable {}
}

