contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt a transfer between two addresses and assert total supply preserved
    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero addrs");

        // Ensure this contract is owner so we can change roles if needed: c was deployed fresh and its owner is the deployer (the checker),
        // but we cannot assume we are owner. We can only interact as this contract (msg.sender for calls). The contract's constructor minted all tokens to deployer,
        // which is not this contract. Therefore we will operate by using approve/transferFrom path if necessary.
        // Instead, we will test behavior when this contract (InvMutTest) initiates transferFrom from itself to recipient.

        // Precondition: make sure this contract has some tokens by attempting to transfer 0 from deployer via transferFrom will revert, so we instead read totalSupply and balances.
        uint256 tBefore = c.totalSupply();

        // Read balances of involved addresses before the call via public balanceOf
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));

        // Try to invoke transfer: since _transfer requires sender or recipient to have allowed role, many transfers will revert.
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state (always allowed reads)
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
