contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will drive a token transfer from an allowed-role sender to a recipient with tAmount < minTxnAmount
    // Parameters: sender (address), recipient (address), tAmount (uint256)
    // Note: msg.sender for calls on c will be this contract, which is the owner/creator of c per problem statement.
    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0) && recipient != address(0), "non-zero addrs");
        // read observable before values
        uint256 minTxn = c.minTxnAmount();
        uint256 beforeContractBal = c.balanceOf(address(c));
        uint256 beforeRecipientReward = c.txReward(recipient);

        // Precondition for the property: tAmount must be strictly less than minTxnAmount
        require(tAmount < minTxn, "tAmount must be < minTxnAmount");

        // Ensure sender is an allowed role by calling changeOwner then relying on owner-only functions is impossible,
        // but _allowedRoles is private. However, the contract's constructor set msg.sender as owner; this test contract
        // is the deployer of c, so it is the owner. Use onlyOwner functions to set state visible: we cannot flip _allowedRoles.
        // Instead, try to simulate an allowed-role transfer by using transferFrom after approving: the contract requires
        // _allowedRoles[sender] || _allowedRoles[recipient] in _transfer; since we cannot modify _allowedRoles, we
        // instead choose the case where recipient is an allowed role by calling c.changeUniswapV2Pair and other owner functions
        // cannot set allowedRoles; therefore we cannot make allowed roles true. To still exercise meaningful rule,
        // assume sender is the owner (which is an allowed role in original constructor). The owner of c is the deployer
        // which is this contract, not the 'sender' parameter. So instead, require sender==address(this) to be allowed.
        require(sender == address(this), "sender must be this contract to match owner/allowed role assumption");

        // Minted tokens were given to deployer (owner) in constructor; this contract (owner) should have balance
        uint256 ownerBal = c.balanceOf(sender);
        require(ownerBal >= tAmount, "insufficient balance for transfer");

        // Perform transfer from sender (this contract) to recipient. This is a state-changing call and must be top-level.
        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterContractBal = c.balanceOf(address(c));
        uint256 afterRecipientReward = c.txReward(recipient);

        // General rule: if transfer succeeded and tAmount < minTxnAmount then txReward[recipient] unchanged and contract balance unchanged
        assert((reverted) || (afterRecipientReward == beforeRecipientReward && afterContractBal == beforeContractBal));
    }

    receive() external payable {}
}

