contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to drive different branches: senderIsAllowed chooses whether
    // the test contract will act as an allowed role (by using existing allowed role logic
    // we cannot directly set _allowedRoles since it's private; instead we exercise
    // transferFrom/transfer with msg.sender being this contract and rely on constructor-set owner
    // However we can only interact via public surface. To test both allowed-role and normal path,
    // we use transfer to unallowed accounts and expect revert unless recipient is allowed.
    // Because _allowedRoles is private and there is no setter, we instead check invariant that
    // totalSupply remains constant after a successful transfer and that balance change equals
    // emitted transfer amounts (observed via balanceOf) and any reward increases txReward when
    // transfer amount >= minTxnAmount.

    // We therefore craft the test to: read totalSupply, balances of sender (this) and recipient,
    // perform transfer to recipient of amount tAmount, catch whether it reverted, then assert
    // that if it did not revert then totalSupply unchanged and balanceOf(recipient) >= old + min(received,tAmount)

    // Because this contract is the deployer of C, msg.sender in C constructor received initial supply.
    // The test contract is not the token owner; but it holds no initial tokens unless c minted to deployer
    // which is the deployer account (outside this test). To ensure the test can send tokens, we will
    // transfer via transferFrom where this contract is spender after approving; however we cannot rely on
    // having tokens. To satisfy the constraint that state-changing calls must be top-level, we craft
    // a general assertion that holds regardless of revert: if transfer succeeded, totalSupply unchanged
    // and recorded balances reflect the transfer and possible reward.

    function run(address recipient, uint256 tAmount) public payable {
        require(recipient != address(0));

        // Observe pre-state
        uint256 supplyBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();
        uint256 contractBalBefore = c.balanceOf(address(c));
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 supplyAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 contractBalAfter = c.balanceOf(address(c));
        uint256 txRewardRecipientAfter = c.txReward(recipient);

        // If the call succeeded then supply must remain and balances must reflect transfer semantics:
        // - total supply unchanged
        // - recipient balance increased by at least the transferred amount (since rewards may add more)
        // - sender balance decreased by the transferred amount
        // - if tAmount >= minTxn and contract had enough balanceBefore, txReward increased by rewardAmount

        uint256 expectedReward = 0;
        if (tAmount >= minTxn) {
            expectedReward = (tAmount * rewardRate) / percent;
        }

        assert(
            // If reverted, nothing else required by this rule
            reverted || (
                // supply unchanged
                supplyAfter == supplyBefore
                // sender decreased by exactly tAmount (unless sender had insufficient tokens; in that case transfer would revert)
                && balSenderBefore >= balSenderAfter
                && balSenderBefore - balSenderAfter == tAmount
                // recipient increased by at least tAmount
                && balRecipientAfter >= balRecipientBefore + tAmount
                // contract's balance decreased by at most expectedReward
                && contractBalBefore >= contractBalAfter
                // if reward applied then txReward increased by expectedReward, but only if contract had enough balanceBefore
                && ( (tAmount < minTxn) || (
                        // either contract didn't have enough balance and no txReward change, or it did and txReward increased by expectedReward
                        (contractBalBefore < expectedReward && txRewardRecipientAfter == txRewardRecipientBefore)
                        || (contractBalBefore >= expectedReward && txRewardRecipientAfter == txRewardRecipientBefore + expectedReward)
                   ) )
            )
        );
    }

    receive() external payable {}
}

