contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising transfers and checking invariants
    function run(address sender, address recipient, uint256 tAmount, bool makeSenderAllowed, bool makeRecipientAllowed) public payable {
        require(sender != address(0) && recipient != address(0) && sender != recipient, "bad addrs");
        // initial observations
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 txRewardSenderBefore = c.txReward(sender);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        // set allowed roles via owner-only change: owner is the contract that deployed c, which is the test runner's deployer,
        // but per constraints we cannot assume we are owner. We instead attempt transfers: allowedRoles are private so we cannot set them.
        // However constructor of C set _owner to deployer of C (external). Since InvMutTest did not deploy C in checker, we cannot call onlyOwner functions.
        // So instead we only assert the conservation and txReward non-increase for the non-privileged case.

        // Make a conservative precondition: require that neither address has txReward or that balances are sufficient to cover tAmount when needed.
        // We will attempt transferFrom by having the test contract approve and transferFrom — but msg.sender seen by C will be this contract
        // and allowances are per owner. We cannot mint tokens to sender; we can only observe public surface. To make the transfer call succeed,
        // use c.transfer which uses msg.sender as sender (InvMutTest). So we will use sender/recipient as arbitrary addresses but perform transfer between this contract and recipient.

        // Instead adapt: perform transfer from this contract (which holds initial minted supply) to recipient or to sender depending on inputs.
        // Observe that constructor of C minted entire supply to deployer of C. The checker deploys fresh C and then constructs this test with that C; the deployer of C is not this contract, so this contract likely has zero balance. To ensure transfer runs, we will try transfers and catch reverts.

        bool reverted;
        // Try transfer from this contract to recipient of tAmount
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observations after attempted transfer
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 txRewardSenderAfter = c.txReward(sender);
        uint256 txRewardRecipientAfter = c.txReward(recipient);

        // General rule asserted:
        // - totalSupply never changes
        // - sum of balances of sender and recipient is unchanged when caller had no privileges to trigger special reward behavior
        //   but since we cannot observe allowedRoles we assert a weaker but general invariant: totalSupply unchanged AND
        //   txReward values never decrease, and when a transfer reverted, balances unchanged for observed accounts.

        // Construct the assertion combining these observable invariants:
        assert(
            // total supply preserved
            totalAfter == totalBefore
            // txReward never decreases for either observed address
            && txRewardSenderAfter >= txRewardSenderBefore
            && txRewardRecipientAfter >= txRewardRecipientBefore
            // if transfer reverted, balances must be unchanged for recipient (and sender)
            && (reverted ? (balRecipientAfter == balRecipientBefore && balSenderAfter == balSenderBefore) : true)
        );
    }

    receive() external payable {}
}

