    // but note changeUniswapV2Pair is onlyOwner, and this test contract is owner because it deployed c in checker assumptions.
    function run(address sender, address recipient, uint256 amount, uint8 useTransferFrom) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero");
        require(sender != recipient, "distinct");

        // read balances before
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));

        bool reverted = false;

        if(useTransferFrom == 1) {
            // set allowance from sender to this test contract if possible: approve must be called by sender, but our test contract cannot act as sender.
            // So we instead call c.transferFrom(sender, recipient, amount) directly; it will only succeed if allowance exists.
            try c.transferFrom(sender, recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Call transfer as sender: since msg.sender for calls from this contract is this contract, we cannot impersonate sender.
            // So call transfer(recipient, amount) which transfers from this contract to recipient.
            // To exercise paths where an "allowed role" check might apply, we perform the transfer from this contract (msg.sender==address(this)).
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read balances after
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 balContractAfter = c.balanceOf(address(c));

        // Invariant: total tokens observable among sender+recipient+contract after equals before, unless the contract paid out a reward (then contract decreased and recipient increased by same amount), or the call reverted in which case nothing changed.
        // We'll assert that either nothing changed when reverted, or the net change of (sender+recipient+contract) equals zero.

        uint256 sumBefore = balSenderBefore + balRecipientBefore + balContractBefore;
        uint256 sumAfter = balSenderAfter + balRecipientAfter + balContractAfter;

        assert(reverted == true && sumBefore == sumAfter || reverted == false && sumBefore == sumAfter);
    }

