contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test function: attempts a transfer from sender to recipient of amount tAmount.
    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero");
        // read pre-state via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeSenderBalance = c.balanceOf(sender);
        uint256 beforeRecipientBalance = c.balanceOf(recipient);
        uint256 beforeContractBalance = c.balanceOf(address(c));

        bool reverted;
        // call transferFrom if allowance exists (this contract is msg.sender to c), otherwise try transfer as sender by using c.transfer via calling c from this contract is not sender; but per constraints msg.sender for calls is this contract.
        // We attempt to perform transfer from sender to recipient by calling transferFrom so that this contract is spender; this will revert if allowance insufficient. We capture revert.
        try c.transferFrom(sender, recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterSenderBalance = c.balanceOf(sender);
        uint256 afterRecipientBalance = c.balanceOf(recipient);
        uint256 afterContractBalance = c.balanceOf(address(c));

        // General rule: totalSupply must never change; and if the call did not revert then the sum of observed balances (sender+recipient+contract) must equal the previous sum
        // Note: balances are tokenFromReflection outputs; we assert equality via addition (no underflow since uint256)
        assert(afterTotal == beforeTotal && (reverted || (afterSenderBalance + afterRecipientBalance + afterContractBalance == beforeSenderBalance + beforeRecipientBalance + beforeContractBalance)));
    }

    receive() external payable {}
 }

